<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Eye, EyeOff, Lock, LockOpen, AlignLeft, AlignCenter, AlignRight, FlipHorizontal2, FlipVertical2, RotateCw, Layers, Grid2X2, Image as ImageIcon, Type, Square, AlignStartVertical, AlignCenterVertical, AlignEndVertical, AlignStartHorizontal, AlignCenterHorizontal, AlignEndHorizontal } from 'lucide-vue-next'
import type { QuoteDesignSection } from '~/utils/quote-design'
import type { DesignerBox } from '~/utils/designer-geometry'
import DataBinding from './DataBinding.vue'
import FourValues from './FourValues.vue'
import Conditions from './Conditions.vue'
import type { RuleResolver } from '~/utils/designer-rules'
import { designerFonts, absoluteLetterSpacing, layerCornerRadii, layerPadding, layerMargins, type DesignerFill } from '~/utils/designer-presentation'
import type { QuoteBindingField } from '~/utils/quote-bindings'
const props = defineProps<{ section: QuoteDesignSection; box?: DesignerBox; pageWidth: number; disabled: boolean; nested?: boolean; kind?: string; parentName?: string; binding?: string; textValue?: string; dataPreview?: string; rowData?: boolean; bindingProtected?: boolean; salesOrder?: boolean; inheritedLocked?: boolean; dataFields?: QuoteBindingField[]; textLimit?: number; fontMin?: number; fontMax?: number; uploadLabel?: string; previewLabel?: string; dataSearchPlaceholder?: string; resetLabel?: string; flowPosition?: boolean; fontUnit?: string; ruleFields?: QuoteBindingField[]; ruleResolver?: RuleResolver; rulesProtected?: boolean; marginValues?: [number, number, number, number] }>()
const emit = defineEmits<{ patch: [patch: Partial<QuoteDesignSection>]; frame: [frame: Partial<DesignerBox>]; command: [value: string]; align: [value: string]; binding: [value: string]; upload: [event: Event] }>()
const moreType = ref(false)
const isText = computed(() => props.kind === 'text' || ['text', 'field'].includes(props.section.kind))
const hasPadding = computed(() => isText.value || ['image', 'table', 'barcode', 'qrcode'].includes(props.kind || '') || props.kind === 'frame' && !props.nested && !['line', 'shape'].includes(props.section.kind))
const weight = computed(() => props.section.fontWeight ?? (props.section.bold ? 700 : 400))
const fillColor = computed(() => isText.value ? props.section.color || '#000000' : props.section.background?.startsWith('#') ? props.section.background : '#ffffff')
const hasFill = computed(() => isText.value ? props.section.fillVisible !== false || props.section.color !== undefined : !!props.section.background && props.section.background !== 'transparent')
const fillDraft = ref<DesignerFill[] | null>(null)
watch(() => [props.section.id, props.section.fills, props.section.color, props.section.background, props.section.fillOpacity, props.section.fillVisible], () => { fillDraft.value = null })
const fills = computed<DesignerFill[]>(() => fillDraft.value || props.section.fills || (hasFill.value ? [{ color: fillColor.value, opacity: props.section.fillOpacity ?? 1, visible: props.section.fillVisible !== false }] : []))
const hasBackground = computed(() => !!props.section.background?.startsWith('#'))
const backgroundColor = computed(() => hasBackground.value ? props.section.background! : '#ffffff')
const palette = ['#000000', '#ffffff', '#64748b', '#2563eb', '#16a34a', '#f97316']
const alignmentIcons = [AlignStartVertical, AlignCenterVertical, AlignEndVertical, AlignStartHorizontal, AlignCenterHorizontal, AlignEndHorizontal]
function number(event: Event, min: number, max: number) {
  const input = event.target as HTMLInputElement
  const value = Number(input.value)
  if (!input.value.trim() || !Number.isFinite(value)) return undefined
  return Math.max(min, Math.min(max, value))
}
function geometry(key: keyof DesignerBox, event: Event) {
  const value = number(event, key === 'width' || key === 'height' ? 1 : props.nested ? -5000 : 0, key === 'width' || key === 'x' ? props.pageWidth : 5000)
  if (value === undefined) return
  const patch: Partial<DesignerBox> = { [key]: value }
  if (props.section.aspectLocked && props.box) {
    if (key === 'width') patch.height = value * props.box.height / props.box.width
    if (key === 'height') patch.width = value * props.box.width / props.box.height
  }
  // The adapter sets fixed sizing together with dimensions in one history transaction.
  emit('frame', patch)
}
function numeric(key: 'rotation' | 'radius' | 'borderWidth' | 'fontSize' | 'letterSpacing' | 'lineHeight' | 'fontWeight' | 'fillOpacity', event: Event, min: number, max: number) {
  const value = number(event, min, max)
  if (value !== undefined) emit('patch', { [key]: value })
}
function rotate() { emit('patch', { rotation: ((props.section.rotation || 0) + 270) % 360 - 180 }) }
function fontWeight(value: number) { emit('patch', { fontWeight: value, bold: value >= 600 }) }
function lineHeight(event: Event) {
  const value = (event.target as HTMLInputElement).value.trim()
  if (!value || value.toLowerCase() === 'auto') emit('patch', { lineHeight: undefined })
  else { const percent = Number(value.replace('%', '')); if (Number.isFinite(percent)) emit('patch', { lineHeight: Math.max(.5, Math.min(4, percent / 100)) }) }
}
function spacingUnit(unit: 'absolute' | 'percent') {
  const size = props.section.fontSize || 12, absolute = absoluteLetterSpacing(props.section.letterSpacing, props.section.letterSpacingUnit, size)
  emit('patch', { letterSpacingUnit: unit, letterSpacing: Math.round((unit === 'percent' ? absolute / size * 100 : absolute) * 100) / 100 })
}
function updateFill(index: number, patch: Partial<DesignerFill>) {
  const next = fills.value.map((fill, i) => i === index ? { ...fill, ...patch } : { ...fill })
  if (props.section.fills || fillDraft.value) { fillDraft.value = next; emit('patch', { fills: next }) }
  else emit('patch', { ...(patch.color ? { [isText.value ? 'color' : 'background']: patch.color } : {}), ...(patch.opacity !== undefined ? { fillOpacity: patch.opacity } : {}), ...(patch.visible !== undefined ? { fillVisible: patch.visible } : {}) })
}
function hexColor(value: string) {
  let hex = value.replace('#', '').trim()
  if (/^[a-f0-9]{3}$/i.test(hex)) hex = hex.split('').map(char => char + char).join('')
  return /^[a-f0-9]{6}$/i.test(hex) ? '#' + hex.toLowerCase() : undefined
}
function paint(value: string, index = 0) {
  const color = hexColor(value)
  if (!color) return
  if (!fills.value.length) emit('patch', { fills: [{ color, opacity: 1, visible: true }] })
  else updateFill(index, { color })
}
function paintBackground(value: string) {
  const background = hexColor(value)
  if (background) emit('patch', { background, ...(!hasBackground.value ? { backgroundOpacity: 1, backgroundVisible: true } : {}) })
}
function removeBackground() { emit('patch', { background: 'transparent', backgroundOpacity: 1, backgroundVisible: true }) }
function addFill() { if (fills.value.length < 8) { fillDraft.value = [{ color: isText.value ? '#000000' : '#d9d9d9', opacity: 1, visible: true }, ...fills.value.map(fill => ({ ...fill }))]; emit('patch', { fills: fillDraft.value }) } }
function removeFill(index: number) {
  if (props.section.fills || fillDraft.value) { fillDraft.value = fills.value.filter((_, i) => i !== index); emit('patch', { fills: fillDraft.value }) }
  else emit('patch', { [isText.value ? 'color' : 'background']: isText.value ? undefined : 'transparent', fillVisible: false })
}
function fillOpacity(event: Event, index = 0) { const value = number(event, 0, 100); if (value !== undefined) updateFill(index, { opacity: value / 100 }) }
function sizePreset(event: Event) { numeric('fontSize', event, props.fontMin || 8, props.fontMax || 120); (event.target as HTMLSelectElement).value = '' }
</script>
<template>
  <section class="element-properties" aria-label="Element design properties">
    <div class="selection-heading"><span class="type-icon"><Grid2X2 v-if="kind === 'table'" /><Layers v-else-if="kind === 'frame'" /><ImageIcon v-else-if="section.kind === 'image'" /><Type v-else-if="isText" /><Square v-else /></span><input :value="section.name || ''" maxlength="80" placeholder="Name this layer" aria-label="Layer name" :disabled="disabled || section.locked" @input="emit('patch', { name: ($event.target as HTMLInputElement).value })" /><button type="button" :disabled="disabled || inheritedLocked" :aria-label="section.locked ? 'Unlock selected layer' : 'Lock selected layer'" @click="emit('patch', { locked: !section.locked })">{{ section.locked ? 'Unlock' : 'Lock' }}</button></div>
    <p v-if="parentName" class="parent-name">{{ parentName }} <span>/ {{ kind || section.kind }}</span></p>
    <p v-if="inheritedLocked" class="layer-note inherited-note">Unlock the parent frame to edit this layer.</p>
    <fieldset :disabled="disabled || section.locked">
      <slot name="content"><DataBinding v-if="kind === 'text' || kind === 'image'" :key="section.id" :kind="kind" :binding="binding" :preview="dataPreview" :row="rowData" :protected="bindingProtected" :sales-order="salesOrder" :nested="nested || section.kind === 'field'" :text="textValue" :fields="dataFields" :maxlength="textLimit" :upload-label="uploadLabel" :preview-label="previewLabel" :search-placeholder="dataSearchPlaceholder" @binding="emit('binding', $event)" @text="emit('patch', { text: $event })" @upload="emit('upload', $event)" /></slot>
      <div class="property-section" aria-label="Position properties">
        <h3>Position</h3><slot name="placement" />
        <label class="field-caption">Alignment</label>
        <div class="segmented layer-align"><button v-for="(icon, index) in alignmentIcons" :key="index" type="button" :aria-label="`Inspector align ${['left','horizontal centers','right','top','vertical centers','bottom'][index]}`" :title="`Align ${['left','horizontal centers','right','top','vertical centers','bottom'][index]}`" @click="emit('align', ['left','center','right','top','middle','bottom'][index])"><component :is="icon" /></button></div>
        <label class="field-caption">Position <span>mm</span></label>
        <div v-if="box" class="fields geometry"><label><span>X</span><input :value="Math.round(box.x * 100) / 100" type="number" step=".5" aria-label="Element X" @change="geometry('x', $event)" /></label><label><span>Y</span><input :value="Math.round(box.y * 100) / 100" type="number" step=".5" aria-label="Element Y" :title="flowPosition ? 'Move vertically while following receipt flow.' : undefined" @change="geometry('y', $event)" /></label></div>
        <p v-else class="layer-note">This layer appears when its document field has a value.</p>
        <label class="field-caption">Rotation</label>
        <div class="fields"><label class="compact-field"><span>&#8736;</span><input :value="section.rotation || 0" type="number" min="-180" max="180" aria-label="Element rotation" @change="numeric('rotation', $event, -180, 180)" /><span>&#176;</span></label><div class="segmented"><button type="button" aria-label="Rotate 90 degrees" title="Rotate 90 degrees" @click="rotate"><RotateCw /></button><button type="button" aria-label="Flip horizontal" title="Flip horizontal" :aria-pressed="section.flipX || false" @click="emit('patch', { flipX: !section.flipX })"><FlipHorizontal2 /></button><button type="button" aria-label="Flip vertical" title="Flip vertical" :aria-pressed="section.flipY || false" @click="emit('patch', { flipY: !section.flipY })"><FlipVertical2 /></button></div></div>
      </div>
      <div class="property-section" aria-label="Layout properties">
        <h3>Layout</h3>
        <template v-if="isText"><label class="field-caption">Resizing</label><div class="segmented resize-modes"><button v-for="mode in [{ key: 'auto-width', icon: '\u2194', label: 'Auto width' }, { key: 'auto-height', icon: '\u2195', label: 'Auto height' }, { key: 'fixed', icon: '\u25a3', label: 'Fixed size' }]" :key="mode.key" type="button" :aria-label="`Text resizing ${mode.label.toLowerCase()}`" :title="mode.label" :aria-pressed="(section.resizeMode || 'fixed') === mode.key" @click="emit('patch', { resizeMode: mode.key as QuoteDesignSection['resizeMode'] })">{{ mode.icon }}<span>{{ mode.label }}</span></button></div></template>
        <label class="field-caption">Dimensions <span>mm</span></label>
        <div class="dimension-row"><div v-if="box" class="fields geometry"><label><span>W</span><input :value="Math.round(box.width * 100) / 100" type="number" min="1" :max="pageWidth" step=".5" aria-label="Element width" @change="geometry('width', $event)" /></label><label><span>H</span><input :value="Math.round(box.height * 100) / 100" type="number" min="1" max="5000" step=".5" aria-label="Element height" @change="geometry('height', $event)" /></label></div><button class="aspect-button" type="button" aria-label="Constrain element proportions" title="Lock aspect ratio" :aria-pressed="section.aspectLocked || false" @click="emit('patch', { aspectLocked: !section.aspectLocked })"><Lock v-if="section.aspectLocked" /><LockOpen v-else /></button></div>
        <template v-if="hasPadding"><FourValues :key="section.id + '-padding'" label="Padding" input-label="Element padding" :values="layerPadding(section)" :individual="!!section.paddingSides" control-id="layer-padding-sides" @all="emit('patch', { padding: $event, paddingSides: undefined })" @individual="emit('patch', { paddingSides: { top: $event[0], right: $event[1], bottom: $event[2], left: $event[3] } })" /><p class="layer-note">Space inside the layer, in millimetres.</p></template>
        <FourValues :key="section.id + '-margin'" label="Margin" input-label="Element margin" :values="marginValues || layerMargins(section, nested ? [0, 0, 0, 0] : [section.gapBefore, 0, section.gapAfter, 0])" :individual="!!section.marginSides" :min="-300" :max="300" control-id="layer-margin-sides" @all="emit('patch', { margin: $event, marginSides: undefined })" @individual="emit('patch', { marginSides: { top: $event[0], right: $event[1], bottom: $event[2], left: $event[3] } })" />
        <p class="layer-note">Space outside the layer, in millimetres.</p>
      </div>
      <div class="property-section" aria-label="Appearance properties"><div class="section-title"><h3>Appearance</h3><button type="button" :disabled="bindingProtected" :aria-label="section.visible === false ? 'Show selected layer' : 'Hide selected layer'" :title="section.visible === false ? 'Show layer' : 'Hide layer'" @click="emit('patch', { visible: section.visible === false })"><EyeOff v-if="section.visible === false" /><Eye v-else /></button></div>
        <FourValues :key="section.id + '-corners'" label="Corner radius" input-label="Element corner radius" :values="layerCornerRadii(section)" :individual="!!section.cornerRadii" corners control-id="layer-corner-radii" @all="emit('patch', { radius: $event, cornerRadii: undefined })" @individual="emit('patch', { cornerRadii: { topLeft: $event[0], topRight: $event[1], bottomRight: $event[2], bottomLeft: $event[3] } })"><template #leading><label>Opacity<div class="compact-field"><span>&#9639;</span><input :value="Math.round((section.opacity ?? 1) * 100)" type="number" min="0" max="100" aria-label="Element opacity" @change="number($event, 0, 100) !== undefined && emit('patch', { opacity: number($event, 0, 100)! / 100 })" /><span>%</span></div></label></template></FourValues>
        <label v-if="section.kind === 'shape' && kind !== 'frame'">Shape<select :value="section.shape || 'rectangle'" aria-label="Shape type" @change="emit('patch', { shape: ($event.target as HTMLSelectElement).value as 'rectangle' | 'ellipse' })"><option value="rectangle">Rectangle</option><option value="ellipse">Ellipse</option></select></label>
        <slot name="appearance" />
      </div>
      <div v-if="isText || $slots.typography" class="property-section" aria-label="Typography properties"><div class="section-title"><h3>Typography</h3><button v-if="isText" type="button" aria-label="More typography options" :aria-expanded="moreType" title="More text options" @click="moreType = !moreType">&#8943;</button></div>
        <template v-if="isText">
          <select :value="section.fontFamily || ''" aria-label="Element font" @change="emit('patch', { fontFamily: (($event.target as HTMLSelectElement).value || undefined) as QuoteDesignSection['fontFamily'] })"><option value="">Page font</option><option v-for="font in designerFonts" :key="font">{{ font }}</option></select>
          <div class="fields"><select :value="weight" aria-label="Element font weight" @change="fontWeight(Number(($event.target as HTMLSelectElement).value))"><option v-for="(name, index) in ['Thin','Extra light','Light','Regular','Medium','Semibold','Bold','Extra bold','Black']" :key="name" :value="(index + 1) * 100">{{ name }}</option></select><div class="compact-field"><input :value="section.fontSize" type="number" :min="fontMin || 8" :max="fontMax || 120" aria-label="Element font size" @change="numeric('fontSize', $event, fontMin || 8, fontMax || 120)" /><select class="size-presets" value="" aria-label="Font size preset" @change="sizePreset"><option value="">&#8964;</option><option v-for="size in [8,9,10,11,12,14,16,18,20,24,28,32,36,48,64,96].filter(n => n >= (fontMin || 8) && n <= (fontMax || 120))" :key="size" :value="size">{{ size }}</option></select></div></div>
          <div class="fields"><label>Line height<input :value="section.lineHeight === undefined ? 'Auto' : Math.round(section.lineHeight * 100) + '%'" type="text" aria-label="Element line height" placeholder="Auto" @change="lineHeight" /></label><label>Letter spacing<div class="compact-field"><input :value="section.letterSpacing || 0" type="number" min="-50" max="200" step=".1" aria-label="Element letter spacing" @change="numeric('letterSpacing', $event, -50, 200)" /><select :value="section.letterSpacingUnit || 'absolute'" aria-label="Letter spacing unit" @change="spacingUnit(($event.target as HTMLSelectElement).value as 'absolute' | 'percent')"><option value="absolute">{{ fontUnit || 'px' }}</option><option value="percent">%</option></select></div></label></div>
          <label class="field-caption">Alignment</label>
          <div class="fields"><div class="segmented"><button v-for="(icon, index) in [AlignLeft, AlignCenter, AlignRight]" :key="index" type="button" :aria-label="`Text align ${['left','center','right'][index]}`" :title="`Align text ${['left','center','right'][index]}`" :aria-pressed="section.align === ['left','center','right'][index]" @click="emit('patch', { align: ['left','center','right'][index] as QuoteDesignSection['align'] })"><component :is="icon" /></button></div><div class="segmented"><button v-for="(icon, index) in [AlignStartHorizontal, AlignCenterHorizontal, AlignEndHorizontal]" :key="index" type="button" :aria-label="`Text vertical align ${['top','middle','bottom'][index]}`" :title="`Align text ${['top','middle','bottom'][index]}`" :aria-pressed="(section.textVerticalAlign || 'top') === ['top','middle','bottom'][index]" @click="emit('patch', { textVerticalAlign: ['top','middle','bottom'][index] as QuoteDesignSection['textVerticalAlign'] })"><component :is="icon" /></button></div></div>
          <div class="segmented text-tools"><button type="button" :aria-pressed="weight >= 600" aria-label="Bold text" @click="fontWeight(weight >= 600 ? 400 : 700)"><b>B</b></button><button type="button" :aria-pressed="section.italic || false" aria-label="Italic text" @click="emit('patch', { italic: !section.italic })"><i>I</i></button><button type="button" :aria-pressed="section.underline || false" aria-label="Underline text" @click="emit('patch', { underline: !section.underline })"><u>U</u></button><button type="button" :aria-pressed="section.strike || false" aria-label="Strikethrough text" title="Strikethrough" @click="emit('patch', { strike: !section.strike })"><s>S</s></button></div>
        </template>
        <div v-if="moreType || !isText" class="typography-extra"><slot name="typography" /></div><button v-if="isText && $slots.typography && !moreType" type="button" class="more-text" @click="moreType = true">More text options</button>
      </div>
      <div v-if="section.kind === 'image'" class="property-section"><h3>Image</h3><select :value="section.imageFit || 'contain'" aria-label="Element image fit" @change="emit('patch', { imageFit: ($event.target as HTMLSelectElement).value as 'contain' | 'cover' })"><option value="contain">Fit</option><option value="cover">Fill</option></select></div>
      <div class="property-section" aria-label="Fill properties"><div class="section-title"><h3>Fill</h3><div class="section-actions"><details class="palette"><summary aria-label="Fill presets" title="Fill presets"><Grid2X2 /></summary><div class="swatches"><button v-for="color in palette" :key="color" type="button" :aria-label="`Fill preset ${color}`" :style="{ background: color }" @click="paint(color)" /></div></details><button type="button" aria-label="Add fill" :disabled="fills.length >= 8" title="Add solid fill (up to 8)" @click="addFill">+</button></div></div>
        <p class="layer-note">{{ isText ? 'Text colour.' : 'Colour inside the layer.' }}</p>
        <div v-for="(fill, index) in fills" :key="index" class="paint-row" :class="{ 'muted-paint': !fill.visible }"><input type="color" :value="fill.color" :aria-label="index ? `Fill ${index + 1} color` : isText ? 'Element text color' : 'Element fill'" @input="paint(($event.target as HTMLInputElement).value, index)" /><input class="hex-input" :value="fill.color.slice(1).toUpperCase()" maxlength="7" :aria-label="index ? `Fill ${index + 1} hex` : 'Element fill hex'" @change="paint(($event.target as HTMLInputElement).value, index)" /><label class="paint-opacity"><input :value="Math.round(fill.opacity * 100)" type="number" min="0" max="100" :aria-label="index ? `Fill ${index + 1} opacity` : 'Fill opacity'" @change="fillOpacity($event, index)" /><span>%</span></label><button type="button" :aria-label="index ? `${fill.visible ? 'Hide' : 'Show'} fill ${index + 1}` : fill.visible ? 'Hide fill' : 'Show fill'" @click="updateFill(index, { visible: !fill.visible })"><EyeOff v-if="!fill.visible" /><Eye v-else /></button><button type="button" :aria-label="index ? `Remove fill ${index + 1}` : 'Remove fill'" @click="removeFill(index)">&#8722;</button></div><p v-if="!fills.length" class="layer-note">No fill</p>
      </div>
      <div v-if="isText" class="property-section" aria-label="Background properties">
        <div class="section-title"><h3>Background</h3><div class="section-actions"><details class="palette"><summary aria-label="Background presets" title="Background presets"><Grid2X2 /></summary><div class="swatches"><button v-for="color in palette" :key="color" type="button" :aria-label="`Background preset ${color}`" :style="{ background: color }" @click="paintBackground(color)" /></div></details><button type="button" :aria-label="hasBackground ? 'Remove background' : 'Add background'" :title="hasBackground ? 'Remove background' : 'Add background colour'" @click="hasBackground ? removeBackground() : paintBackground('#ffffff')">{{ hasBackground ? '-' : '+' }}</button></div></div>
        <p class="layer-note">Colour behind the text.</p>
        <div v-if="hasBackground" class="paint-row" :class="{ 'muted-paint': section.backgroundVisible === false }"><input type="color" :value="backgroundColor" aria-label="Element background color" @input="paintBackground(($event.target as HTMLInputElement).value)" /><input class="hex-input" :value="backgroundColor.slice(1).toUpperCase()" maxlength="7" aria-label="Element background hex" @change="paintBackground(($event.target as HTMLInputElement).value)" /><label class="paint-opacity"><input :value="Math.round((section.backgroundOpacity ?? 1) * 100)" type="number" min="0" max="100" aria-label="Background opacity" @change="number($event, 0, 100) !== undefined && emit('patch', { backgroundOpacity: number($event, 0, 100)! / 100 })" /><span>%</span></label><button type="button" :aria-label="section.backgroundVisible === false ? 'Show background' : 'Hide background'" @click="emit('patch', { backgroundVisible: section.backgroundVisible === false })"><EyeOff v-if="section.backgroundVisible === false" /><Eye v-else /></button></div>
        <p v-else class="layer-note">No background</p>
      </div>
      <div class="property-section" aria-label="Stroke properties"><div class="section-title"><h3>Stroke</h3><button type="button" :aria-label="section.borderWidth ? 'Remove stroke' : 'Add stroke'" @click="emit('patch', { borderWidth: section.borderWidth ? 0 : .3, borderColor: section.borderColor || '#cbd5e1' })">{{ section.borderWidth ? '-' : '+' }}</button></div><p class="layer-note">Outline around the layer.</p><div v-if="section.borderWidth" class="paint-row"><input type="color" :value="section.borderColor || '#cbd5e1'" aria-label="Element stroke color" @input="emit('patch', { borderColor: ($event.target as HTMLInputElement).value })" /><input class="hex-input" :value="(section.borderColor || '#cbd5e1').slice(1).toUpperCase()" aria-label="Stroke hex" maxlength="7" @change="/^#?[a-f0-9]{6}$/i.test(($event.target as HTMLInputElement).value) && emit('patch', { borderColor: '#' + ($event.target as HTMLInputElement).value.replace('#','') })" /><label class="paint-opacity"><input :value="section.borderWidth" type="number" min="0" max="5" step=".1" aria-label="Element stroke width" @change="numeric('borderWidth', $event, 0, 5)" /><span>mm</span></label></div><slot name="stroke" /></div>
      <slot name="properties" /><Conditions v-if="ruleResolver" :rules="section.rules" :fields="ruleFields || dataFields || []" :resolve="ruleResolver" :text="isText" :protected="rulesProtected" @change="emit('patch', { rules: $event })" /><slot name="visibility" />
      <details class="property-section more-options"><summary>Layer actions</summary><div class="buttons"><button type="button" @click="emit('command', 'back')">Send to back</button><button type="button" @click="emit('command', 'front')">Bring to front</button><button type="button" @click="emit('command', 'flow')">{{ resetLabel || 'Reset position & size' }}</button></div></details>
    </fieldset>
  </section>
